insert into countries (slug,kind,country_name,country_code,flag,from_code,to_code,visa_name,card_note,h1,meta_title,meta_description,intro,embassy_fee_text,embassy_fee_pkr,vfs_fee_text,service_fee_pkr,processing_time_text,max_stay_text,apply_window_text,biometrics_text,facts_source_url,facts_last_checked,who_for_md,documents,funds_md,steps,refusal_reasons,extra_sections,related_slugs,keywords,licensed_partner,is_published,sort_order) values ('uk-visit-visa-from-pakistan','visit','United Kingdom','GB','gb','KHI','LHR','Standard Visitor visa','TOURISM · FAMILY','UK Visit Visa from Pakistan','UK Visit Visa from Pakistan: Fees & Documents | Visafeast','UK Standard Visitor visa from Pakistan: documents, bank statement advice, fees and timelines with the date we last checked. Free eligibility check.','Planning a trip to United Kingdom? We check your documents, explain your funds properly and prepare a file that matches your plan.','£135 (up to 6 months). Long-term: 2 years £506 · 5 years £903 · 10 years £1,128 (6 months per visit)',null,null,null,'Usually within 3 weeks','Up to 6 months per visit','Earliest 3 months before travel','Fingerprints and photo at a visa application centre','https://www.gov.uk/standard-visitor/apply-standard-visitor-visa','2026-10-23','["Tourists and holiday travellers","Families visiting relatives or friends","Business visitors attending meetings or conferences","First-time travellers who want a file prepared properly"]'::jsonb,'[{"title":"Passport (plus old passports)","detail":"Valid passport and all previous passports with travel history."},{"title":"6 months of bank statements","detail":"Personal or business statements that show regular income and a steady balance."},{"title":"Proof of job or business","detail":"Employment letter, payslips, or business registration."},{"title":"FBR tax returns (NTN)","detail":"Recent tax returns if you file them."},{"title":"Travel plan","detail":"Dates and places you plan to visit. Flights do not need to be booked before applying."},{"title":"Invitation letter (if visiting someone)","detail":"From the host in the UK, with their status and address."},{"title":"Sponsor documents (if sponsored)","detail":"The sponsor''s statements and a letter explaining the relationship."},{"title":"Family ties","detail":"FRC, marriage certificate and similar documents showing links to Pakistan."},{"title":"Property or other assets (optional)","detail":"Shows ties and financial stability."}]'::jsonb,'There is no fixed amount set by UK Visas and Immigration. The officer checks three things: that your funds cover the full trip, that they match your income, and that the money has been in your account long enough to be explained. A large deposit shortly before applying is one of the most common refusal reasons. If someone else pays for your trip, include their statements and a letter explaining the relationship.','[{"title":"Free 15-minute call","detail":"Tell us where you want to go and why. We tell you honestly what to prepare."},{"title":"File review","detail":"We check your documents against the official list and point out weak spots before you pay any embassy fee."},{"title":"Preparation","detail":"Your personal checklist, a clear travel plan and a cover letter that explains your funds and purpose."},{"title":"Application support","detail":"Help with the online form, payment steps and appointment booking."},{"title":"Decision and next steps","detail":"We update you on WhatsApp. If a file is refused, we read the letter and plan the next step honestly."}]'::jsonb,'[{"title":"Unexplained deposits","detail":"Large sums that appear just before applying, with no clear source."},{"title":"Weak ties to Pakistan","detail":"The officer is not convinced you will return."},{"title":"Inconsistent details","detail":"Dates, jobs or amounts that do not match across documents."},{"title":"Unclear purpose","detail":"No clear reason or plan for the trip."}]'::jsonb,'[]'::jsonb,'{"canada-visit-visa-from-pakistan","schengen-visa-from-pakistan","study-in-uk-from-pakistan"}'::text[],'{"uk","united kingdom","gb","uk visas and immigration"}'::text[],null,true,10) on conflict (slug) do nothing;
