insert into faqs (country_id,question,answer_md,sort_order) values (null,'Do you guarantee a visa?','No. No honest consultant can — only the embassy decides. What we promise is a complete, consistent file and an honest opinion of your chances before you pay embassy fees.',0);
insert into faqs (country_id,question,answer_md,sort_order) values (null,'How much bank balance do I need for a UK visit visa?','There is no fixed official amount. The officer checks that your funds cover the trip and match your income history. We review your statements in the free call.',1);
insert into faqs (country_id,question,answer_md,sort_order) values (null,'I was refused before. Can you help?','Yes. Send us the refusal letter; we address every point raised and tell you honestly if it''s better to wait.',2);
insert into faqs (country_id,question,answer_md,sort_order) values (null,'I live outside Karachi. Can I still use Visafeast?','Yes. Consultations run on WhatsApp video or phone; you attend biometrics at your nearest VFS/visa centre.',3);
insert into faqs (country_id,question,answer_md,sort_order) values (null,'How long does processing take?','Depends on the country and season; each country page shows the current official time with the date we last checked it.',4);
insert into faqs (country_id,question,answer_md,sort_order) values (null,'Do you help with immigration and PR?','Yes — skilled, family and business pathways for Canada, Australia, the UK, USA, Germany, New Zealand and parts of Europe. Where the law requires a licensed representative, your case is filed with our licensed partners.',5);
insert into faqs (country_id,question,answer_md,sort_order) values (null,'Can I read the website in Urdu?','Yes. Use the EN / اردو switch at the top. Checklists and WhatsApp updates are available in Urdu too.',6);
insert into faqs (country_id,question,answer_md,sort_order) select id,'How early can I apply?','Up to 3 months before you travel. Decisions are usually made within 3 weeks, so applying 6–8 weeks ahead is sensible.',0 from countries where slug='uk-visit-visa-from-pakistan';
insert into faqs (country_id,question,answer_md,sort_order) select id,'Should I apply for a 2, 5 or 10-year visa straight away?','It is possible, but you must show genuine repeat visits. The long-term fee is not refunded if the application is refused, so first-time travellers usually start with 6 months.',1 from countries where slug='uk-visit-visa-from-pakistan';
insert into faqs (country_id,question,answer_md,sort_order) select id,'Do I need to book flights before applying?','No. A travel plan with dates is enough.',2 from countries where slug='uk-visit-visa-from-pakistan';
insert into faqs (country_id,question,answer_md,sort_order) select id,'Can I work on a UK visit visa?','No. Meetings and conferences are fine, but not paid work.',3 from countries where slug='uk-visit-visa-from-pakistan';
